contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint256 mintedAmount) public payable {
        require(target != address(0));
        // Read before-values
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeBal = c.balanceOf(target); if (__ESBMC_reverted()) return;

        // Try calling mintToken and record whether it reverted
        bool reverted;
        c.mintToken(target, mintedAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterBal = c.balanceOf(target); if (__ESBMC_reverted()) return;

        // The general rule:
        // If mintToken did not revert then afterTotal == beforeTotal + mintedAmount
        // and afterBal == beforeBal + mintedAmount. If it reverted then both values unchanged.
        assert((!reverted && afterTotal == beforeTotal + mintedAmount && afterBal == beforeBal + mintedAmount) ||
               (reverted && afterTotal == beforeTotal && afterBal == beforeBal));
    }

    receive() external payable {}
}

